from shapely.geometry import Point

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class DynamicPoint(Point):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            for field in fields:
                setattr(self, field, kwargs.get(field, None))
            self.srid = srid_map.get(self.geom_type, None)

    DynamicPoint.__name__ = name
    return DynamicPoint

import warnings
from functools import wraps

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

import functools

def cached(cache, key=hash, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if k in cache:
                return cache[k]
            if lock is not None:
                with lock:
                    if k not in cache:
                        cache[k] = func(*args, **kwargs)
            else:
                cache[k] = func(*args, **kwargs)
            return cache[k]
        return wrapper
    return decorator

from functools import wraps
from collections import OrderedDict

class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = OrderedDict()
        self.freq = {}
        self.min_freq = 0

    def __call__(self, func):
        @wraps(func)
        def wrapper(*args):
            key = args if not self.typed else (args, type(args))
            if key in self.cache:
                self.freq[key] += 1
                self.cache.move_to_end(key)
                return self.cache[key]
            else:
                if len(self.cache) >= self.maxsize:
                    while self.min_freq not in self.freq or self.freq[self.min_freq] == 0:
                        self.min_freq += 1
                    lfu_key = next(iter(self.cache))
                    del self.cache[lfu_key]
                    del self.freq[lfu_key]
                result = func(*args)
                self.cache[key] = result
                self.freq[key] = 1
                self.min_freq = 1
                return result
        return wrapper

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    return LFUCache(maxsize, typed)

class OrderedDict:
    def __init__(self):
        self.items = []

    def popitem(self):
        """Remove and return the `(key, value)` pair first inserted."""
        if not self.items:
            raise KeyError("popitem(): dictionary is empty")
        return self.items.pop(0)

    def __setitem__(self, key, value):
        self.items.append((key, value))

    def __getitem__(self, key):
        for k, v in self.items:
            if k == key:
                return v
        raise KeyError(key)

    def __contains__(self, key):
        for k, _ in self.items:
            if k == key:
                return True
        return False

    def __repr__(self):
        return f"OrderedDict({self.items})"

