def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a set to track unique base classes
    unique_bases = set()
    # Create a list to maintain the order of first appearance
    ordered_bases = []

    for base in classes:
        if base not in unique_bases:
            unique_bases.add(base)
            ordered_bases.append(base)

    return ordered_bases

