def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        if isinstance(item, tuple):
            output.extend(item)
        else:
            output.append(item)

    return output

class Histogram:
    def __init__(self, initial_value=0, make_bins=None):
        self.context = {}
        self.initial_value = initial_value
        self.make_bins = make_bins
        self.reset()

    def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        self.context = {}
        if self.make_bins is not None:
            self.make_bins()
        else:
            self.context = {key: self.initial_value for key in self.context.keys()}

