import numpy as np

class DataProcessor:
    def __init__(self, data, errors):
        self.data = data
        self.errors = errors

    def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        if coord_name not in self.data:
            raise ValueError(f"Coordinate name '{coord_name}' not found in data.")

        coord_values = self.data[coord_name]
        error_threshold = np.mean(coord_values) + 2 * np.std(coord_values)
        err_indices = np.where(self.errors > error_threshold)[0]

        return err_indices

import copy

class Graph:
    def __init__(self, data):
        self.data = data
        self.error_indices = {}

    def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        if 'error' not in context:
            context['error'] = {}

        for key, value in self.data.items():
            if key.startswith('error_'):
                error_name = key.split('_')[1]
                if error_name not in context['error']:
                    context['error'][error_name] = {}
                context['error'][error_name]['index'] = value

        # Simplify error names to "x", "y", "z" if possible
        if 'x' not in context['error'] and 'E' in context['error']:
            context['error']['x'] = context['error']['E']
        if 'y' not in context['error'] and 't' in context['error']:
            context['error']['y'] = context['error']['t']
        if 'z' not in context['error'] and 'error_E_low' in context['error']:
            context['error']['z'] = context['error']['error_E_low']

