def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1

    if level == 0:
        return d1

    diff = {}
    for key in d1:
        if key not in d2:
            diff[key] = d1[key]
        else:
            sub_diff = difference(d1[key], d2[key], level - 1)
            if sub_diff:
                diff[key] = sub_diff

    return diff

import re
from typing import Dict, Any, List

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(str(messages))

def _validate_labels(labels: Dict[str, Any]):
    key_regex = re.compile(r'^[a-zA-Z0-9_]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_]+$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue

        if not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex {key_regex.pattern}"})

        if isinstance(value, str):
            if not value_regex.match(value):
                errors.append({value: f"Label value '{value}' does not match the regex {value_regex.pattern}"})
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                elif not value_regex.match(item):
                    errors.append({item: f"Label value '{item}' does not match the regex {value_regex.pattern}"})
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

# Example usage
labels = {
    "key1": "valid",
    "key2": ["invalid"],
    "$$": "invalid",
    True: True,
}

try:
    _validate_labels(labels)
except ValidationError as err:
    assert err.messages == [
        {"['invalid']": 'expected string or bytes-like object'},
        {'$$': "Label key '$$' does not match the regex ^[a-zA-Z0-9_]+$"},
        {'True': 'expected string or bytes-like object'},
        {'True': 'expected string or bytes-like object'},
    ]

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            observer_schema[key] = None

    if first_level:
        # Copy values of identifying fields from the manifest file
        identifying_fields = ['apiVersion', 'kind', 'metadata']
        for field in identifying_fields:
            if field in manifest_dict:
                observer_schema[field] = manifest_dict[field]

    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for i, (observed_field, response_item) in enumerate(zip(observer_schema, response)):
        if i < len(last_applied_manifest):
            if isinstance(observed_field, dict) and isinstance(response_item, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[i], observed_field, response_item
                )
            elif isinstance(observed_field, list) and isinstance(response_item, list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[i], observed_field, response_item
                )
            else:
                last_applied_manifest[i] = response_item
        else:
            last_applied_manifest.append(response_item)
def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, observed_field in observer_schema.items():
        if key in response:
            if isinstance(observed_field, dict) and isinstance(response[key], dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest.get(key, {}), observed_field, response[key]
                )
            elif isinstance(observed_field, list) and isinstance(response[key], list):
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest.get(key, []), observed_field, response[key]
                )
            else:
                last_applied_manifest[key] = response[key]
        else:
            last_applied_manifest[key] = None

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, value in observer_schema.items():
        if isinstance(value, dict):
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            if key not in response:
                raise KeyError(f"The observed field '{key}' is not present in the Kubernetes response")
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], observer_schema[key], response[key])
        elif isinstance(value, list):
            if key not in last_applied_manifest:
                last_applied_manifest[key] = []
            if key not in response:
                raise KeyError(f"The observed field '{key}' is not present in the Kubernetes response")
            # Assuming the list contains dictionaries and we need to update each item
            for i, item in enumerate(observer_schema[key]):
                if i >= len(response[key]):
                    raise KeyError(f"The observed field '{key}' does not have enough items in the Kubernetes response")
                if i >= len(last_applied_manifest[key]):
                    last_applied_manifest[key].append({})
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[key][i], item, response[key][i])
        else:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response.get(key)

