if __name__ == "__main__":
    sql = "SELECT * FROM users WHERE name = :name AND age > :age"
    params = {"name": "Alice", "age": 30}
    formatted_sql, formatted_params = format(sql, params)
    print("Formatted SQL:", formatted_sql)
    print("Formatted Params:", formatted_params)

import os
import json

class OCFLValidator:
    def validate(self, path):
        """Validate OCFL object at path or pyfs root.

        Returns True if valid (warnings permitted), False otherwise.
        """
        if not os.path.exists(path):
            return False

        if not os.path.isdir(path):
            return False

        if not os.path.exists(os.path.join(path, '0=ocfl_object_1.0')):
            return False

        if not os.path.exists(os.path.join(path, 'inventory.json')):
            return False

        with open(os.path.join(path, 'inventory.json'), 'r') as f:
            try:
                inventory = json.load(f)
            except json.JSONDecodeError:
                return False

        if 'id' not in inventory or 'head' not in inventory or 'versions' not in inventory:
            return False

        for version in inventory['versions']:
            if 'manifest' not in version:
                return False

            manifest_path = os.path.join(path, version['manifest'])
            if not os.path.exists(manifest_path):
                return False

            with open(manifest_path, 'r') as f:
                try:
                    manifest = json.load(f)
                except json.JSONDecodeError:
                    return False

            for file_path in manifest:
                if not os.path.exists(os.path.join(path, file_path)):
                    return False

        return True

