class InventoryValidator:
    def __init__(self, inventory):
        self.inventory = inventory

    def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if not isinstance(prior, InventoryValidator):
            raise ValueError("The prior must be an InventoryValidator object.")

        current_items = set(self.inventory.items())
        prior_items = set(prior.inventory.items())

        # Check if all items in the prior inventory are present in the current inventory
        if not prior_items.issubset(current_items):
            raise ValueError("The prior inventory contains items not present in the current inventory.")

        # Check if the quantities in the prior inventory are less than or equal to the current inventory
        for item, quantity in prior.inventory.items():
            if self.inventory.get(item, 0) < quantity:
                raise ValueError(f"The quantity of item '{item}' in the prior inventory exceeds the current inventory.")

        return True

