class ExpressionProcessor:
    def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        def simplify_expression(expr):
            if isinstance(expr, tuple):
                op, left, right = expr
                if op == '&':
                    if left == right:
                        return left
                    if isinstance(left, tuple) and left[0] == '|' and left[1] == right:
                        return right
                    if isinstance(right, tuple) and right[0] == '|' and right[1] == left:
                        return left
                elif op == '|':
                    if left == right:
                        return left
                    if isinstance(left, tuple) and left[0] == '&' and left[1] == right:
                        return right
                    if isinstance(right, tuple) and right[0] == '&' and right[1] == left:
                        return left
            return expr

        simplified_args = [simplify_expression(arg) for arg in args]
        return simplified_args

# Example usage:
processor = ExpressionProcessor()
expressions = [
    ('&', ('&', 'A', ('|', 'A', 'B')), 'B'),
    ('|', ('|', 'A', ('&', 'A', 'B')), 'B'),
    ('&', ('&', 'A', ('|', ('~', 'A'), 'B')), 'B'),
    ('|', ('|', 'A', ('&', ('~', 'A'), 'B')), 'B')
]
simplified_expressions = processor.absorb(expressions)
print(simplified_expressions)

