HookType = TypeVar('HookType')

class HookRegistry:
    def __init__(self):
        self.registry: Dict[HookType, list[Callable]] = {}

    def on(self, hook: HookType) -> Callable[[Callable], Callable]:
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified hook.
        """
        def decorator(func: Callable) -> Callable:
            if hook not in self.registry:
                self.registry[hook] = []
            self.registry[hook].append(func)
            return func
        return decorator

