from datetime import datetime, timezone, timedelta

class CustomTimeZone:
    def __init__(self, offset):
        self.offset = offset

    def utcoffset(self, dt):
        return self.offset

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "CustomTimeZone"

    def _fromutc(self, dt):
        if dt.tzinfo is not self:
            raise ValueError("dt.tzinfo must be self")

        # Calculate the local time
        local_time = dt.replace(tzinfo=None) - self.offset

        # Check for ambiguous times
        ambiguous = False
        if self.dst(local_time + timedelta(hours=1)) != timedelta(0):
            ambiguous = True

        # Determine the fold state
        fold = 0
        if ambiguous:
            # Check if the given time is the first occurrence
            if local_time + self.offset == dt:
                fold = 1

        # Return the timezone-aware datetime with fold information
        return local_time.replace(fold=fold, tzinfo=self)

# Example usage
if __name__ == "__main__":
    tz = CustomTimeZone(timedelta(hours=-5))
    dt = datetime(2023, 11, 5, 1, 30, tzinfo=timezone.utc)
    new_dt = tz._fromutc(dt)
    print(new_dt)

import sys

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if sys.version_info[0] < 3:
        return lambda: map(lambda x: x.encode('utf-8') if isinstance(x, unicode) else x, namefunc())
    else:
        return namefunc

