import os
import hashlib

class VersionValidator:
    def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        root_inventory = self._load_inventory('root')
        previous_inventory = {}
        content_digests = {}

        for version_dir in version_dirs:
            inventory_path = os.path.join(version_dir, 'inventory')
            if not os.path.exists(inventory_path):
                raise FileNotFoundError(f"Inventory file not found in {version_dir}")

            current_inventory = self._load_inventory(inventory_path)

            # Check if current inventory contains all items from previous inventories
            for item, digest in previous_inventory.items():
                if item not in current_inventory or current_inventory[item] != digest:
                    raise ValueError(f"Inventory mismatch for item {item} in version {version_dir}")

            # Update previous inventory with current inventory
            previous_inventory.update(current_inventory)

            # Record content digests different from root inventory
            for item, digest in current_inventory.items():
                if item in root_inventory and root_inventory[item] != digest:
                    content_digests[item] = digest

        return content_digests

    def _load_inventory(self, inventory_path):
        inventory = {}
        with open(inventory_path, 'r') as file:
            for line in file:
                item, digest = line.strip().split(',')
                inventory[item] = digest
        return inventory

import os

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not os.path.exists(path):
        return "Path does not exist"

    if os.path.isfile(path):
        return "file"

    if not os.path.isdir(path):
        return "Path is not a directory"

    namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]

    if len(namaste_files) == 0:
        return "No Namaste file found"

    if len(namaste_files) > 1:
        return "Multiple Namaste files found"

    namaste_file = namaste_files[0]

    with open(os.path.join(path, namaste_file), 'r') as f:
        content = f.read().strip()

    if content == "OCFL Storage Root":
        return "root"
    elif content == "OCFL Object":
        return "object"
    else:
        return f"Unexpected Namaste file content: {content}"

