import argparse

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = unparsed_arguments[:]

    for subparser_name, subparser in subparsers.items():
        # Try to parse the arguments with the current subparser
        try:
            # Parse known arguments and collect unknown ones
            namespace, unknown_args = subparser.parse_known_args(remaining_args)
            parsed_args[subparser_name] = namespace
            remaining_args = unknown_args
        except argparse.ArgumentError:
            # If parsing fails, continue to the next subparser
            continue

    return parsed_args, remaining_args

