import subprocess
import os
from typing import Optional, Union
from pathlib import Path

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[Path, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    if not tmp_path.exists():
        tmp_path.mkdir(parents=True)

    if filename is None:
        filename = os.path.basename(archive_path).rsplit('.', 1)[0]

    extract_path = tmp_path / filename

    if archive_path.endswith('.zip'):
        subprocess.run(['unzip', archive_path, '-d', extract_path], check=True)
    elif archive_path.endswith('.tar.gz'):
        subprocess.run(['tar', '-xzf', archive_path, '-C', extract_path], check=True)
    elif archive_path.endswith('.tar'):
        subprocess.run(['tar', '-xf', archive_path, '-C', extract_path], check=True)
    else:
        raise ValueError("Unsupported archive format")

    return f"file://{extract_path}"

import datetime
import re

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    # Define a regex pattern to match numbers and units
    pattern = r'(\d+)\s*(seconds?|minutes?|hours?|days?|weeks?|months?|years?)'
    match = re.match(pattern, frequency)

    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    # Extract the number and unit from the match
    number = int(match.group(1))
    unit = match.group(2).lower()

    # Map units to timedelta arguments
    unit_map = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
        'month': 'days',  # Approximate month as 30 days
        'months': 'days',  # Approximate month as 30 days
        'year': 'days',  # Approximate year as 365 days
        'years': 'days'   # Approximate year as 365 days
    }

    # Create a timedelta object
    if unit in unit_map:
        if unit_map[unit] == 'days' and (unit == 'month' or unit == 'months'):
            return datetime.timedelta(days=number * 30)
        elif unit_map[unit] == 'days' and (unit == 'year' or unit == 'years'):
            return datetime.timedelta(days=number * 365)
        else:
            return datetime.timedelta(**{unit_map[unit]: number})
    else:
        raise ValueError(f"Unsupported unit: {unit}")

