from typing import Optional, Set

def find_roots(
    graph: "rdflib.Graph", prop: "rdflib.URIRef", roots: Optional[Set["rdflib.Node"]] = None
) -> Set["rdflib.Node"]:
    if roots is None:
        roots = set(graph.subjects(predicate=prop))

    for root in list(roots):
        for s, p, o in graph.triples((None, prop, root)):
            roots.discard(s)
            roots.add(s)

    return roots

