def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != len(make_value(make_value(hist.bins[0]))):
        raise ValueError("The number of field names must match the number of values returned by make_value")

    graph_data = []
    for i, bin_ in enumerate(hist.bins):
        if get_coordinate == "left":
            x = hist.edges[i]
        elif get_coordinate == "right":
            x = hist.edges[i + 1]
        elif get_coordinate == "middle":
            x = (hist.edges[i] + hist.edges[i + 1]) / 2

        values = make_value(bin_)
        graph_data.append((x,) + tuple(values))

    return Graph(graph_data, field_names, scale=scale)

