from zope.interface import Interface, implementer, Invalid, providedBy
from inspect import signature, Parameter

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    # Check if candidate claims to provide the interface
    if not tentative and not providedBy(candidate, iface):
        errors.append(f"Candidate does not claim to provide {iface}")

    # Check if candidate defines all necessary methods
    for name, method in iface.namesAndDescriptions():
        if not callable(getattr(candidate, name, None)):
            errors.append(f"Candidate does not define method {name}")

    # Check if methods have the correct signature
    for name, method in iface.namesAndDescriptions():
        if callable(getattr(candidate, name, None)):
            candidate_method = getattr(candidate, name)
            iface_method = method
            iface_signature = signature(iface_method)
            candidate_signature = signature(candidate_method)

            if iface_signature.parameters.keys() != candidate_signature.parameters.keys():
                errors.append(f"Method {name} has incorrect signature")

    # Check if candidate defines all necessary attributes
    for name, attribute in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            errors.append(f"Candidate does not define attribute {name}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

from zope.interface import Interface, implementer, Invalid, providedBy
from inspect import signature

def verifyObject(iface, candidate, tentative=False):
    if not tentative and not providedBy(candidate, iface):
        raise Invalid(f"{candidate} does not provide {iface}")

    missing_methods = []
    missing_attributes = []
    incorrect_signatures = []

    for name, method in iface.namesAndDescriptions():
        if not callable(getattr(candidate, name, None)):
            missing_methods.append(name)
        else:
            try:
                if signature(getattr(candidate, name)) != signature(method):
                    incorrect_signatures.append(name)
            except TypeError:
                # If the method is a descriptor, we can't compare signatures
                pass

    for name in iface.names():
        if not hasattr(candidate, name):
            missing_attributes.append(name)

    errors = []
    if missing_methods:
        errors.append(f"Missing methods: {', '.join(missing_methods)}")
    if incorrect_signatures:
        errors.append(f"Incorrect signatures: {', '.join(incorrect_signatures)}")
    if missing_attributes:
        errors.append(f"Missing attributes: {', '.join(missing_attributes)}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type) or not isinstance(candidate, type):
        raise ValueError("Both iface and candidate must be types (classes).")

    if tentative:
        return issubclass(candidate, iface)
    else:
        return issubclass(candidate, iface) and all(hasattr(candidate, attr) for attr in iface.__abstractmethods__)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        metaclasses.add(base.__class__)

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, use type as the default
    return type

