class Validator:
    @classmethod
    def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise ValueError("yaml_file parameter is required")

        yaml_path = Path(yaml_file)
        if not yaml_path.exists():
            raise FileNotFoundError(f"YAML file {yaml_file} does not exist")

        with open(yaml_path, 'r') as file:
            data = yaml.safe_load(file)

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a valid dictionary")

        required_fields = ['field1', 'field2', 'field3']  # Replace with actual required fields
        missing_fields = [field for field in required_fields if field not in data]

        if missing_fields:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing_fields)}")

        return data

import json

class SpecFileParser:
    def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if 'include' in parser_dict:
            include_dict = parser_dict['include']
            for key, value in include_dict.items():
                if isinstance(value, str):
                    with open(value, 'r') as file:
                        included_content = json.load(file)
                        parser_dict[key] = included_content
                elif isinstance(value, dict):
                    parser_dict[key] = self._include_groups(value)
        return parser_dict

