import re

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for option in options_spec:
        if 'required_when' in option:
            condition = option['required_when']
            if self._evaluate_condition(condition, args):
                required_args.append(option['name'])
    return required_args

def _evaluate_condition(self, condition, args):
    """Evaluate the condition string against the provided arguments.

    :param condition: the condition string to evaluate.
    :param args: the received input arguments.
    :return: bool, True if the condition is met, False otherwise.
    """
    # Replace placeholders in the condition with actual argument values
    for arg_name, arg_value in args.items():
        placeholder = f'{{{arg_name}}}'
        if placeholder in condition:
            condition = condition.replace(placeholder, str(arg_value))

    # Evaluate the condition as a Python expression
    try:
        return eval(condition)
    except Exception as e:
        raise ValueError(f"Error evaluating condition '{condition}': {e}")

