import argparse

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Define a dictionary to map argument names to their expected types
    type_map = {
        'main': {
            'int_arg': int,
            'float_arg': float,
            'bool_arg': lambda x: x.lower() in ['true', '1', 't', 'y', 'yes']
        },
        'virsh': {
            'memory': int,
            'vcpus': int
        },
        'ospd': {
            'port': int,
            'debug': lambda x: x.lower() in ['true', '1', 't', 'y', 'yes']
        }
    }

    # Get the type map for the given parser_name
    parser_type_map = type_map.get(parser_name, {})

    # Iterate over the values_dict and convert values to the correct types
    for key, value in values_dict.items():
        if key in parser_type_map:
            try:
                values_dict[key] = parser_type_map[key](value)
            except (ValueError, TypeError) as e:
                raise argparse.ArgumentTypeError(f"Invalid value for {key}: {value}") from e

import os
import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec_path = os.path.join(plugin_dir, 'plugin.json')

    if not os.path.exists(plugin_spec_path):
        raise FileNotFoundError(f"Plugin spec file not found at {plugin_spec_path}")

    with open(plugin_spec_path, 'r') as file:
        plugin_spec = json.load(file)

    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(plugin_spec)

